{
  "name": "opencode-model-failover",
  "version": "0.1.8",
  "description": "Native model failover for OpenCode v2: move a failed session onto the next healthy model in a chain you define.",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "model-failover",
    "model-fallback",
    "failover",
    "rate-limit",
    "quota",
    "resilience",
    "llm",
    "ai-coding-agent"
  ],
  "license": "MIT",
  "author": "Nabheet S. Sandhu",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nabheet/opencode-model-failover.git"
  },
  "bugs": {
    "url": "https://github.com/nabheet/opencode-model-failover/issues"
  },
  "homepage": "https://github.com/nabheet/opencode-model-failover#readme",
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "lint": "biome check . && markdownlint-cli2 \"**/*.md\" \"#node_modules/**\" \"#dist/**\" \"#.git/**\"",
    "lint:fix": "biome check --write . && markdownlint-cli2 --fix \"**/*.md\" \"#node_modules/**\" \"#dist/**\" \"#.git/**\"",
    "check": "npm run lint && npm test",
    "test": "node --test test/*.test.mjs"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.6.2",
    "markdownlint-cli2": "^0.24.0"
  },
  "overrides": {
    "katex": "^0.19.1",
    "re2js": "2.8.7"
  }
}
